  ('hb-wuhan-opc-2026', '武汉市支持人工智能OPC创新发展若干措施', '湖北', '武汉市', '算力与模型', ARRAY["算力服务券","免费算力","创新创业"]::text[], '2026-02-14', '2026-03-18', '2028-12-31', '武政规〔2026〕4号', '武汉市人民政府', '市级', 'direct', '现行有效', '围绕算力、数据、模型、空间、人才、投融资和场景应用支持AI加超级个体创业。', ARRAY["算力使用费用50%补助、最高20万元且不超过3年","各区每年为每家OPC提供不少于2000卡时免费算力"]::text[], ARRAY["具备AI应用开发与整合能力的人才或微型团队创办的OPC","以大模型、AI编程、智能体等为核心工具"]::text[], '算力券等项目按武汉市数据、经信及各区后续申报通知执行。', NULL, '武汉市人民政府', '政策原文', 'https://jgswgl.wuhan.gov.cn/xxgk_59/zc/zcwj/202602/t20260225_2731775.shtml', '2026-09-03'),
  ('gd-shenzhen-opc-2026', '深圳市打造人工智能OPC创业生态引领地行动计划（2026—2027年）', '广东', '深圳市', '空间载体', ARRAY["OPC社区","应用场景","成果转化"]::text[], '2026-01-15', NULL, '2027-12-31', '深工信〔2026〕2号', '深圳市工业和信息化局', '市级', 'direct', '规划期内', '布局高质量OPC社区，整合人才、产业、空间、科研和出海服务资源，建设全国人工智能创业生态引领地。', ARRAY["示范应用项目最高给予200万元研发资助","符合条件的联合攻关项目最高可获3000万元资助"]::text[], ARRAY["在深圳开展人工智能创新创业的企业和团队","具体项目需符合对应研发计划或社区认定规则"]::text[], '通过深圳各区OPC社区、工业和信息化主管部门及对应研发计划申报。', 'https://amr.sz.gov.cn/xxgk/qt/ztlm/opcfwzq/', '深圳市人民政府', '政策原文', 'https://www.sz.gov.cn/cn/xxgk/zfxxgj/tzgg/content/post_12602687.html', '2026-09-03'),
  ('hn-csjkq-opc-measures-2026', '长沙经济技术开发区管委会关于印发《长沙经济技术开发区关于智能体和“一人公司”开源社区安全发展的十条措施》的通知', '湖南', '长沙经济技术开发区（星沙）', '资金与融资', ARRAY["OPC社区","智能体","算力券","开源社区"]::text[], '2026-04-10', NULL, NULL, NULL, '长沙经济技术开发区管理委员会', '区县级', 'direct', '现行有效', '从培育OPC创新主体、创业平台/基地、AI大赛、智能体算力普惠、数据开发、未来场景与开源生态等方面，出台十条措施支持智能体和“一人公司”（OPC）开源社区安全发展。', ARRAY["新认定高新技术企业的OPC企业奖励15万元（分3年拨付）","国家级制造业单项冠军、国家级专精特新“小巨人”、省级专精特新中小企业分别奖励50万/30万/5万元；独角兽最高100万元、瞪羚最高20万元","国家级创新创业大赛一、二、三等奖分别支持30万/20万/10万元，省级15万/10万/5万元，园区“满天星”大赛5万/3万/2万元","验收合格的“满天星”创业基地最高10万元一次性建设补贴；创业指导工作室最高20万元服务补贴","国产智能算力算力券按年度实际发生额10%补助、最高100万元；垂类模型或垂类数据集一次性最高50万元奖励","数据服务费用按10%补贴、单个企业最高100万元；示范项目最高100万元，单个场景最高50万元、单个企业最高补助500万元","开源平台按实际投入5%奖励、单个平台最高300万元"]::text[], ARRAY["智能体与“一人公司”（OPC）企业、创业团队及开源社区相关主体","与园区“1+N”政策体系衔接，细则见长经开管发〔2025〕59/58/62号等文件"]::text[], '本措施由经开区经济发展局（安全生产监管局）负责解释；完整条款与兑现方式按通知原文及园区实施细则执行。', NULL, '长沙经济技术开发区管理委员会', '政策原文', 'http://cetz.changsha.gov.cn/zsyz_43810/zszc/202604/t20260410_12357499.html', '2026-09-03'),
  ('sx-xian-opc-measures-2026', '西安市市场监督管理局出台《支持一人公司（OPC）创业发展若干措施》（八项举措）', '陕西', '西安市', '合规与登记', ARRAY["准入服务","信用赋能","沙盒监管","轻创业者"]::text[], '2026-07-20', NULL, NULL, NULL, '西安市市场监督管理局', '市级', 'direct', '现行有效', '西安市市场监管局对标杭州、成都、武汉等地经验出台专项扶持措施，从准入开办、合规服务、创新赋能、精准监管四个维度推出八项全链条举措，服务一人公司（OPC）轻资产、低成本、灵活创新。', ARRAY["开设OPC专属服务专区，企业开办全流程网办，新增AI新业态专属申报选项","支持非货币资产出资、自主约定认缴期限，推行固定工位、集群注册登记模式，落实歇业休眠制度","编制OPC专属合规指引与风险清单，建立“一户一档”信用档案，推行简易修复、线上一键修复","依托知识产权公益特派员提供一对一帮扶和集中托管，完善快速维权、线上调解及海外预警服务","对新业态探索沙盒监管模式，设置1至3年观察期，落实扫码入企与轻微违法“三项清单”"]::text[], ARRAY["一人公司（OPC）：涵盖一人有限责任公司、个人独资企业、个体工商户等轻量化创业主体","依托人工智能开展自主经营的“AI+超级个体”式创业者"]::text[], '原文为西安市市场监管局官方发布稿（含一图读懂）；办理入口见市监系统OPC专属服务专区及属地政务窗口。', NULL, '西安市市场监督管理局', '官方发布', 'https://scjg.xa.gov.cn/xwzx/sjdt/2085566200442548226.html', '2026-09-03'),
  ('gd-haizhu-opc-measures-2026', '广州市海珠区人工智能发展局关于印发《广州市海珠区人工智能OPC创新发展措施（试行）》的通知', '广东', '广州市海珠区', '资金与融资', ARRAY["算力补贴","Token","OPC加速器","以赛代评"]::text[], '2026-06-24', NULL, NULL, NULL, '广州市海珠区人工智能发展局', '区县级', 'direct', '试行', '海珠区印发二十条试行措施，衔接区人工智能产业“十大行动”，围绕智能体服务专区、OPC特色孵化空间、加速器、要素保障、生态活动、场景开放、适配工具、金融服务与政务服务等培育“单人+AI即公司”生态。', ARRAY["年度累计有效订单100/200/500个分别最高扶持2万/5万/10万元；大额订单最高20万元；单个OPC企业每年最高30万元经营扶持","使用智能体工具开展业务给予最高20万元算力补贴（按日均token或大模型调用量分档）","OPC特色孵化空间运营主体按细则最高150万元扶持；场景项目最高500万元；生态活动项目最高50万元","智能体开发类OPC首次完成国家级生成式AI上线备案最高100万元、完成算法备案最高20万元","依托琶洲算法大赛提供“以赛代评”快速通道与“微种子+成长期权+投贷联动”资本支持"]::text[], ARRAY["在海珠区内诚信经营、无重大安全事故、财务健全独立核算、主营业务与人工智能产业相关的OPC（人员规模一般不超过10人）","按本措施可享受扶持的产业空间运营主体"]::text[], '本措施自印发之日起试行一年，具体申报指南由海珠区人工智能发展局另行制定；咨询电话 020-89557116 / 89559824，地址：广州市海珠区琶洲大道83号宝地广场1001室。同一年度市、区同类扶持按就高不重复。', NULL, '广州市人民政府（行政规范性文件发布平台）', '政策原文', 'https://www.gz.gov.cn/gfxwj/qjgfxwj/hzq/qbm/content/post_10869848.html', '2026-09-03'),
  ('gx-nanning-msa-opc-measures-2026', '南宁市市场监督管理局印发《支持人工智能OPC创新创业发展的若干举措》', '广西', '南宁市', '合规与登记', ARRAY["一址多照","集群注册","沙盒监管","个转企"]::text[], '2026-06-16', NULL, NULL, NULL, '南宁市市场监督管理局', '市级', 'direct', '现行有效', '南宁市市场监管局从OPC快速办理通道、登记服务、入市指导、风险防范、知识产权保护与运用、信用柔性管理、成长培育等方面推出若干举措，服务人工智能OPC轻装上阵、合规经营。', ARRAY["开通OPC快速办理通道：企业开办全程“网上办、智慧办、一日办、零成本”，线下设OPC服务专窗与帮办代办","实施“一址多照”“集群注册”，支持个体工商户、个人独资企业“个转企”直接转型为OPC并保留原信用代码、字号","依托商标品牌指导站提供“多合一”一站式知识产权保护，支持专利快速预审与商标注册、专利质押融资","推行信用风险分级分类监管与失信预警，审慎列入经营异常名录；在OPC创业园区探索“沙盒监管”模式并设观察期","强化公平竞争审查“三重双审”，保障OPC平等获得资源、公平参与市场竞争"]::text[], ARRAY["人工智能OPC（One Person Company，一人公司）创业者及个体工商户、个人独资企业转型主体","直播带货、社交电商、内容创作、在线服务等网络新业态经营者"]::text[], '原文为南宁市市场监管局官方发布（南宁市市场监管局牵头、南宁日报发布）；具体登记与申报以属地市场监管部门办事指南为准。', NULL, '南宁市人民政府门户（南宁日报）', '官方发布', 'https://www.nanning.gov.cn/ywzx/bmdt/2026nbmdt/t6661354.html', '2026-09-03'),
  ('sc-opc-action-2026', '关于印发《四川省支持人工智能OPC创新发展行动方案（2026—2027年）》的通知', '四川', '四川省', 'OPC创业', ARRAY["行动方案","OPC企业培育","16项任务"]::text[], '2026-04-17', NULL, '2027-12-31', NULL, '四川省科学技术厅（四川省科学技术厅网站发布）', '省级', 'direct', '规划期内', '四川省出台支持人工智能OPC创新发展的省级行动方案（2026—2027年），部署16项重点任务，目标到2027年底培育人工智能OPC企业超1000家（口径与四川在线、人民网四川等官方发布同源）。', ARRAY["目标到2027年底培育人工智能OPC企业超1000家","部署16项重点任务，由省委组织部、省委金融办、省发展改革委、经济和信息化厅、人社厅、省市场监管局等部门按职责协同落实"]::text[], ARRAY["人工智能OPC（AI一人公司）企业及相关创新创业主体","省级各部门按职责分工细化落实（详见行动方案原文）"]::text[], '行动方案原文见四川省科技厅官网发布页；具体支持事项与申报窗口以各牵头部门后续通知为准。', NULL, '四川省科学技术厅', '政策原文', 'https://kjt.sc.gov.cn/kjt/gstz/2026/4/17/454bbd76e963409a8193f9bcfc5af121.shtml', '2026-09-03'),
  ('bj-chaoyang-opc-measures-2026', '朝阳园管委会（区科信局）等四部门关于印发《朝阳区关于支持人工智能OPC创新发展的若干措施》的通知', '北京', '北京市朝阳区', '资金与融资', ARRAY["算力券","词元券","OPC社区","SICN"]::text[], '2026-05-14', '2026-05-14', '2029-05-14', '中朝管发〔2026〕5号', '中关村科技园区朝阳园管理委员会、北京市朝阳区科学技术和信息化局等四部门', '区县级', 'direct', '现行有效', '朝阳区聚焦“培育OPC实际是投资于人”，从OPC特色创业社区、生产工具与算力数据供给、场景开放、词元补贴、人才服务与SICN（超级个体网络）等方面出台若干措施，打造具有全国影响力的OPC创业集聚地。', ARRAY["符合条件的OPC社区运营服务机构可获连续三年、每年最高500万元资金支持","优质智能体工具/AIGC平台每年最高补助500万元（连续不超过三年）","OPC使用算力券、词元券开展研发创新，按实际使用金额50%支持、每年最高50万元","创新性场景项目按研发与建设投资额（不含土建）的30%支持、单个最高500万元","打造SICN超级个体网络，提供资源链接、商务谈判、品牌营销等经纪服务","OPC人才可申报“朝阳青创15条”并纳入中小企业梯度培育政策"]::text[], ARRAY["OPC（人工智能一人公司）及朝阳区OPC社区运营服务机构、平台企业","在朝阳区内注册经营、诚信守法的相关创新创业主体"]::text[], '原文见朝阳区政府网政策文件栏目（成文2026-05-06、发布2026-05-14、有效期至2029-05-14）；申报细则以区科信局等四部门后续指南为准。', NULL, '北京市朝阳区人民政府（朝阳园管委会等四部门）', '政策原文', 'http://www.bjchy.gov.cn/affair/file/otherfile/4028805a9dfdb457019e25a981de22c6.html', '2026-09-03'),
  ('ln-opc-plan-2026', '辽宁省人工智能OPC培育发展实施方案（2026—2028年）', '辽宁', '辽宁省', 'OPC创业', ARRAY["实施方案","OPC培育","落地奖励"]::text[], '2026-05-12', NULL, '2028-12-31', NULL, '辽宁省人工智能创新发展工作专班办公室（省发展改革委）', '省级', 'direct', '规划期内', '辽宁省发布人工智能OPC培育发展实施方案（2026—2028年），统筹算力、数据要素、OPC社区与产业联盟等资源，培育“AI+超级个体”新型组织形态。', ARRAY["“一人公司”落地最高奖3万元（辽宁日报媒体解读口径）","目标到2028年培育一批AI OPC创业主体（报道口径拟培育300家）","统筹市级算力服务平台，强化数据要素与算力资源普惠供给，推动组建市级OPC产业联盟"]::text[], ARRAY["人工智能OPC（在AI协同下完成全链路业务闭环的个人/微型组织）及其社区载体"]::text[], '以省政府新闻发布会实录为官方口径（2026-05-12发布）；正式文件全文见辽宁省政府门户政策文件栏目，申报配套以专班及各市后续通知为准。', NULL, '辽宁省人民政府（新闻发布会实录）', '政策原文', 'https://www.ln.gov.cn/web/spzb/2026nxwfbh/2026051215571269816/index.shtml', '2026-09-03'),
  ('tj-nine-opc-measures-2026', '天津市人社局等16部门《关于加快打造“一人公司”创新创业生态的若干措施》', '天津', '天津市', 'OPC创业', ARRAY["创业券","创客驿站","担保贷款","订单撮合"]::text[], '2026-09-02', NULL, NULL, NULL, '天津市人力资源和社会保障局等16部门', '省级', 'direct', '现行有效', '天津市人社局等16部门制定若干措施，从准入通道、全链条服务平台、载体支持、应用场景、订单导入、创业培训、特色信贷、运营商招引与赛事跟踪等方面加快打造“一人公司”（OPC）创新创业生态。', ARRAY["深化个人创业“一件事”，提供登记、纳税、社保等“1+N”高效服务，支持非货币财产出资","打造市级OPC创业公共服务平台；支持国家超算互联网、360等建设大模型生态服务平台","发放“创业券”提供财税、金融、法律、人力资源、知识产权等服务；为38周岁以下来津创业者提供最长3年“创客驿站”住宿","创业担保贷款：个人最高30万元、企业最高400万元并予贴息支持","引导京东、抖音、腾讯、360、云账户等在津平台发布AI应用场景订单，组织OPC承接","依托“海河英才”等赛事设OPC专项赛道，获奖项目优先入驻孵化基地并跟进扶持"]::text[], ARRAY["“一人公司”（OPC）创业主体及有意向创业的个人","各类创业孵化基地、众创空间载体运营机构"]::text[], '依据新华社天津频道2026-09-02发布口径；正式文件名称、文号及申报细则以天津市政府及主管部门正式印发文本为准。', NULL, '新华社天津频道', '官方发布', 'http://www.tj.xinhua.org/20260902/e6c1a17ca7ed4042bbb275061f6b86b5/c.html', '2026-09-03'),
  ('sd-opc-action-2026', '山东省12部门印发《关于支持人工智能OPC创新发展的行动方案》', '山东', '山东省', 'OPC创业', ARRAY["算力券","语料券","模型券","场景券","济青烟"]::text[], '2026-07-31', NULL, NULL, NULL, '山东省工业和信息化厅等12部门', '省级', 'direct', '现行有效', '山东省12部门联合印发支持人工智能OPC创新发展行动方案，部署基础能力跃升、平台载体提质、企业梯度培育、应用场景拓展、人才引育聚力和金融赋能保障六大重点行动。', ARRAY["总体目标：力争3年内建成百个特色载体、培育千家AI OPC创业主体、集聚万名创新人才","落地“算力券”“语料券”“模型券”“场景券”等奖补政策，降低算力/数据/模型使用门槛","允许以“工位号”、集群注册方式为OPC提供共享办公，支持济青烟打造AI OPC特色园区","建设OPC数据沙箱与隐私计算平台，开放公共数据“可用不可见”","创新“研发贷”“模型贷”“知识产权贷”“视听版权贷”等特色信贷产品","支持高校设“人工智能+X”微专业、开OPC创业成长培训，构建“创业陪跑”机制"]::text[], ARRAY["人工智能OPC创业主体、特色园区/社区载体、数据与算力服务相关企业"]::text[], '行动方案全文经青岛市工信局2026-07-31转载核验（省工信厅发布口径见其官网）；文号与各地市申报细则以山东省工信厅及各市后续通知为准。', NULL, '山东省工业和信息化厅（青岛市工信局全文转载）', '政策原文', 'http://gxj.qingdao.gov.cn/zcwj/202607/t20260731_10691302.shtml', '2026-09-03'),
  ('zj-ningbo-opc-2026', '宁波市人民政府办公厅关于支持人工智能OPC创新创业发展的若干意见', '浙江', '宁波市', '资金与融资', ARRAY["若干意见","政策兑现","亲清在线"]::text[], '2026-07-17', NULL, NULL, NULL, '宁波市人民政府办公厅', '市级', 'direct', '现行有效', '宁波市政府办公厅出台支持人工智能OPC创新创业发展的若干意见（含官方政策解读与图解），配套实施细则在“亲清在线/政策早知道”平台上线兑现。', ARRAY["媒体报道口径：符合条件者可获最高200万元补助类支持（以实施细则为准）","配套官方政策解读、图解与“亲清在线”政策兑现入口"]::text[], ARRAY["在宁波开展人工智能OPC创新创业的企业、团队与个人（条件以实施细则为准）"]::text[], '原文、官方解读与兑现细则见宁波市政府门户及“亲清在线”平台；具体申报条件与金额口径以文件原文和实施细则为准。', NULL, '宁波市人民政府', '政策原文', 'https://www.ningbo.gov.cn/col/col1229533176/art/2026/art_f6775b1c40df4f8080ef63113d889941.html', '2026-09-03'),
  ('js-wuxi-opc-guide-2026', '无锡市市场监督管理局等发布《无锡市人工智能OPC企业市场准入便利化服务指引（试行）》', '江苏', '无锡市', '合规与登记', ARRAY["集群注册","市场准入","数据确权","OPC社区备案"]::text[], '2026-06-16', NULL, NULL, NULL, '无锡市市场监督管理局、无锡市数据局', '市级', 'direct', '试行', '无锡市市场监管局联合市数据局发布人工智能OPC企业市场准入便利化服务指引（试行），打造“园区托管—登记注册—数据确权—股权出资—梯度培育—金融赋能”六大闭环服务链条，并推出多项市场准入便利化举措。', ARRAY["OPC社区备案极简办：产业园、孵化器、商务秘书企业提交基础资料与信用承诺即可申请托管备案，开展集群托管","集群注册一站落户：企业开办全流程网办、电子签章，凭OPC社区登记信息一站落户","发布会同步推出政策服务、金融支持、知识产权护航等多领域服务“大礼包”"]::text[], ARRAY["人工智能OPC（一人公司）创业主体及OPC社区运营机构（园区/孵化器/商务秘书企业）"]::text[], '指引全文与申报办理见无锡市市场监管局官网（2026-06-16发布）；发布会于无锡（国家）软件园魔方空间OPC社区举办。', NULL, '无锡市市场监督管理局', '官方发布', 'https://scjgj.wuxi.gov.cn/doc/2026/06/16/4791426.shtml', '2026-09-03'),
